int ni(dynamic v)=>v is num?v.toInt():int.tryParse('$v')??0; double nd(dynamic v)=>v is num?v.toDouble():double.tryParse('$v')??0; String now()=>DateTime.now().toIso8601String().substring(0,10); String uid()=>DateTime.now().microsecondsSinceEpoch.toString();

