class Store extends ChangeNotifier{
 late SharedPreferences prefs; List<Map<String,dynamic>> shops=[]; int active=0; bool get registered=>shops.isNotEmpty; Map<String,dynamic> get shop=>registered?shops[active]:{};
 List<Map<String,dynamic>> list(String k)=>(shop[k] as List???[]).whereType<Map>().map((e)=>Map<String,dynamic>.from(e)).toList(); List<Map<String,dynamic>>get items=>list('items');List<Map<String,dynamic>>get customers=>list('customers');List<Map<String,dynamic>>get issued=>list('issued');List<Map<String,dynamic>>get returns=>list('returns');
 Future<void>load()async{prefs=await SharedPreferences.getInstance();try{shops=(jsonDecode(prefs.getString('shops')??'[]')as List).whereType<Map>().map((e)=>Map<String,dynamic>.from(e)).toList();}catch(_){ }active=prefs.getInt('active')??0;if(shops.isNotEmpty&&active>=shops.length)active=0;}
 Map<String,dynamic>makeShop(String n,String o,String p,String a)=>{'id':uid(),'name':n,'owner':o,'phone':p,'address':a,'items':<Map<String,dynamic>>[],'customers':<Map<String,dynamic>>[],'issued':<Map<String,dynamic>>[],'returns':<Map<String,dynamic>>[]};
 Future<void>save()async{await prefs.setString('shops',jsonEncode(shops));await prefs.setInt('active',active);} Future<void>addShop(String n,String o,String p,String a)async{shops.add(makeShop(n,o,p,a));active=shops.length-1;await save();notifyListeners();} Future<void>updateShop(Map<String,String>d)async{shop.addAll(d);await save();notifyListeners();} Future<void>deleteShop(int i)async{shops.removeAt(i);if(active>=shops.length)active=shops.isEmpty?0:shops.length-1;await save();notifyListeners();} Future<void>select(int i)async{active=i;await save();notifyListeners();} Future<void>changed()async{await save();notifyListeners();}
}
