Future<void>itemForm(BuildContext c,Store s,{Map<String,dynamic>?old})async{final n=TextEditingController(text:'${old?['name']??''}'),code=TextEditingController(text:'${old?['code']??''}'),days=TextEditingController(text:'${old?['rentDays']??1}');final ok=await showDialog<bool>(context:c,builder:(d)=>AlertDialog(title:Text(old==null?'Add Item':'Edit Item'),content:Column(mainAxisSize:MainAxisSize.min,children:[TextField(controller:n,decoration:const InputDecoration(labelText:'Item name')),TextField(controller:code,decoration:const InputDecoration(labelText:'Code')),TextField(controller:days,decoration:const InputDecoration(labelText:'Rent days'),keyboardType:TextInputType.number)]),actions:[TextButton(onPressed:()=>Navigator.pop(d),child:const Text('Cancel')),FilledButton(onPressed:()=>Navigator.pop(d,true),child:const Text('Save'))]));if(ok==true){final x=old??{'id':uid(),'srl':s.items.length+1};x['name']=n.text;x['code']=code.text;x['rentDays']=ni(days.text);if(old==null)s.items.add(x);await s.changed();}}
