Future<void>preview(BuildContext c,Store s,Map<String,dynamic>e)async{await showDialog(context:c,builder:(d)=>AlertDialog(title:Text('Invoice ${e['invoice']}'),content:SingleChildScrollView(child:Column(crossAxisAlignment:CrossAxisAlignment.start,children:[Text('${e['customerName']} • ${e['mobile']}'),Text('${e['address']}'),const Divider(),...(e['items']as List).map((x)=>Text('SRL ${x['srl']}  ${x['item']}  Qty ${x['qty']}'))])),actions:[TextButton(onPressed:()=>Navigator.pop(d),child:const Text('Close')),FilledButton.icon(onPressed:()async{final pdf=pw.Document();pdf.addPage(pw.Page(pageFormat:PdfPageFormat.a4,build:(_)=>pw.Column(crossAxisAlignment:pw.CrossAxisAlignment.start,children:[pw.Text('RentFlow',style:pw.TextStyle(fontSize:24,fontWeight:pw.FontWeight.bold)),pw.Text('By PaliaAPK HUB'),pw.SizedBox(height:15),pw.Text('Invoice: ${e['invoice']}'),pw.Text('Date: ${e['date']}'),pw.Text('Customer: ${e['customerName']}'),pw.Text('Mobile: ${e['mobile']}'),pw.Text('Address: ${e['address']}'),pw.SizedBox(height:12),...(e['items']as List).map((x)=>pw.Text('SRL ${x['srl']}  ${x['item']}  Qty ${x['qty']}  Rent days ${x['rentDays']}')),pw.SizedBox(height:20),pw.Text('Developer by shanpalia')]));await Printing.layoutPdf(onLayout:(_)=>pdf.save());},icon:const Icon(Icons.picture_as_pdf),label:const Text('PDF'))]));}
